def misuse_get_total_number_of_sequences(m, n):
    # dp[i][j] represents the number of valid sequences of length j ending with value i
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: sequence of length 1 ending at i (for i >= 1)
    for i in range(1, m + 1):
        dp[i][1] = 1

    # Fill DP table
    for j in range(2, n + 1):
        for i in range(1, m + 1):
            # Previous element must be <= i/2
            prev_limit = i // 2
            if prev_limit == 0:
                continue
            count = 0
            for prev in range(1, prev_limit + 1):
                count += dp[prev][j - 1]
            dp[i][j] = count

    return dp[m][n]

