```python
def misuse_uniquePaths(m, n):
    if m <= 0 or n <= 0:
        return 0
    sol = [[0 for j in range(n)] for i in range(m)]
    sol[0][0] = 1
    for i in range(m):
        for j in range(n):
            if i == 0 or j == 0:
                sol[i][j] = 1
            else:
                sol[i][j] = sol[i - 1][j] + sol[i][j - 1]
    return sol[m - 1][n - 1]
```

